// st03bs.ecl.txt:512-622. Source t0=card124; first burst source90=card214.
const TIME_LIMIT: int = 2522;
const SOURCE_LIMIT: int = 2400;
const TH18_RICE: int = 480;

xformdef CLOUD(e: angle, f: angle) {
    // Native on_tick handler reentry consumes OFFSCREEN 5 extra times at finite boundaries.
    offscreen_keep(195);
    @30 set_gravity(at_effect((1.5fx-$self_speed)/30*cos($self_angle)),
                    at_effect((1.5fx-$self_speed)/30*sin($self_angle)));
    @10 set_gravity(0fx, 0fx);
    @30 set_gravity(at_effect((0.5fx/30)*cos(aim_player()+e)),
                    at_effect((0.5fx/30)*sin(aim_player()+e)));
    @30 set_gravity(at_effect((-1.97fx/30)*cos($self_angle)),
                    at_effect((-1.97fx/30)*sin($self_angle)));
    @30 set_gravity(at_effect((1.97fx/30)*cos(aim_player()+f)),
                    at_effect((1.97fx/30)*sin(aim_player()+f)));
    // Last VELTIME follows current vector. Signed polar speed preserves crossing through zero.
    // Its source logical speed has endpoints 2 -> 1, independently of actual vector magnitude.
    @64 set_accel(-0.0083333333fx);
    @1 set_accel(-0.0166666667fx); // age194: OFFSCREEN end reenters VELTIME once before integration
    @54 set_accel(-0.0083333333fx);
    stop_fx(); // age249: 120 VELTIME updates completed, including the doubled update at194
}
sub burst(offset: angle) {
    var rank: int = global(GVAR_RANK);
    var n: int = 20;
    if rank == 1 { n = 60; }
    if rank == 2 { n = 45; }
    if rank == 3 { n = 55; }
    var d: angle = rand(65536) as angle;
    var e: angle = rand(65536) as angle;
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 2);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 7, 1);
    for j in 0..n {
        // Source increments D/E before the first emission, not after.
        var g: angle = d+(((j+1)*65536/(n*7)) as angle);
        var a: angle = e+(((j+1)*65536/n) as angle);
        sh_angle(0, g, 0deg);
        sh_xform(0, CLOUD(a, a+offset));
        sh_dist(0, -6fx); // ANIM a1 retreats four times this layer's original 1.5 speed.
        sh_speed(0, 1.5fx, 0fx);
        sh_fire(0);
        if rank >= 2 {
            // Same 7 initial angles, zero-speed source layer; no retreat and no RNG consumption.
            sh_dist(0, 0fx);
            sh_speed(0, 0fx, 0fx);
            sh_fire(0);
        }
    }
}
async sub pattern() {
    wait(120);
    set_self_int(2, $frame);
    set_self_int(1, $frame+SOURCE_LIMIT);
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(90);
    var offset: angle = 90deg;
    loop {
        if $frame >= self_int(1) { return; }
        burst(offset);
        offset = -offset;
        card_wait(120);
        if $frame >= self_int(1) { return; }
        card_move_rand();
        card_wait(120);
    }
}
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    spell_begin(0, 20, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH18 v1.00a BossCard1 only. int0=next-step, int1=source end, int2=source start, int3=sampled ray count; fx0/1=logical unit vector.
// All source wait(n) inside this attack must use card_wait(n), in the same owner task.
// No new task: emit uses the current position, phase5 then performs the next source movement tick.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -60fx { nx = -60fx; }
    if nx > 60fx { nx = 60fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -30fx {
        a = r/3;
    } else if $self_x > 30fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}
